def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            # Determine the base ASCII value for uppercase or lowercase
            if char.isupper():
                base = ord('A')
            else:
                base = ord('a')
            # Shift by 4 (2 * 2)
            shifted = (ord(char) - base + 4) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)
